   261|  const compressed: IVXRetrievalResult[] = [];
   262|  let usedTokens = 0;
   263|
   264|  for (const r of results) {
   265|    const tokens = Math.ceil(r.content.length / 4);
   266|    if (usedTokens + tokens > maxTokens) {
